-- Re-assert the scenario state for an already-present john (e.g. a hand-created
-- dev row): link to the firm-1 person and expose the firm-5 whitelabel host.
UPDATE entity_tbl
   SET linked_gw_user = '6459DFB4414B47DE9BFE9AC06205BD43',
       system_base_url = 'john.localhost',
       cp_whitelabel_keyword = 'jhn'
 WHERE entity_id = '019E8978F9AE7676915751838956A526'
   AND ( linked_gw_user IS NULL
      OR system_base_url IS NULL
      OR cp_whitelabel_keyword IS NULL );

COMMIT;
